import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class SecureVault {
    private static final int KEY_SIZE = 32;
    private static final int MAC_SIZE = 32;
    private static final int IV_SIZE = 16;
    private static final int MAX_ENTRY_SIZE = 1 << 20; // 1MB

    private final byte[] encKey;
    private final byte[] macKey;
    private final ConcurrentHashMap<String, byte[]> storage = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> acl = new ConcurrentHashMap<>();

    public SecureVault(byte[] masterSecret) {
        if (masterSecret == null || masterSecret.length < 64)
            throw new IllegalArgumentException("Master secret too short");
        this.encKey = Arrays.copyOfRange(masterSecret, 0, KEY_SIZE);
        this.macKey = Arrays.copyOfRange(masterSecret, KEY_SIZE, KEY_SIZE * 2);
    }

    public String store(String userId, String entryName, byte[] plaintext) throws Exception {
        if (plaintext == null || plaintext.length == 0)
            throw new IllegalArgumentException("Empty plaintext");
        if (plaintext.length > MAX_ENTRY_SIZE)
            throw new IllegalArgumentException("Entry too large");
        if (!isValidIdentifier(userId) || !isValidIdentifier(entryName))
            throw new IllegalArgumentException("Invalid identifier");

        byte[] iv = new byte[IV_SIZE];
        SecureRandom.getInstanceStrong().nextBytes(iv);

        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(encKey, "AES"),
                   new IvParameterSpec(iv));
        byte[] ciphertext = cipher.doFinal(plaintext);

        // MAC covers: iv || length(4 bytes big-endian) || ciphertext
        byte[] lengthBytes = new byte[4];
        lengthBytes[0] = (byte)((ciphertext.length >> 24) & 0xFF);
        lengthBytes[1] = (byte)((ciphertext.length >> 16) & 0xFF);
        lengthBytes[2] = (byte)((ciphertext.length >> 8) & 0xFF);
        lengthBytes[3] = (byte)(ciphertext.length & 0xFF);

        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(macKey, "HmacSHA256"));
        mac.update(iv);
        mac.update(lengthBytes);
        mac.update(ciphertext);
        byte[] tag = mac.doFinal();

        // Wire format: [iv(16)] [tag(32)] [length(4)] [ciphertext(N)]
        byte[] blob = new byte[IV_SIZE + MAC_SIZE + 4 + ciphertext.length];
        System.arraycopy(iv, 0, blob, 0, IV_SIZE);
        System.arraycopy(tag, 0, blob, IV_SIZE, MAC_SIZE);
        System.arraycopy(lengthBytes, 0, blob, IV_SIZE + MAC_SIZE, 4);
        System.arraycopy(ciphertext, 0, blob, IV_SIZE + MAC_SIZE + 4, ciphertext.length);

        String entryId = userId + ":" + entryName;
        storage.put(entryId, blob);
        acl.put(entryId, userId);
        return entryId;
    }

    public byte[] retrieve(String userId, String entryId) throws Exception {
        if (!isValidIdentifier(userId))
            throw new SecurityException("Invalid user");

        String owner = acl.get(entryId);
        if (owner == null)
            throw new SecurityException("Entry not found");
        if (!MessageDigest.isEqual(owner.getBytes(StandardCharsets.UTF_8),
                                   userId.getBytes(StandardCharsets.UTF_8)))
            throw new SecurityException("Access denied");

        byte[] blob = storage.get(entryId);
        if (blob == null)
            throw new SecurityException("Entry not found");

        return decryptBlob(blob);
    }

    /**
     * Import an externally-created encrypted blob.
     * Used for migration from legacy systems.
     * Validates MAC before storing.
     */
    public String importBlob(String userId, String entryName, byte[] blob) throws Exception {
        if (!isValidIdentifier(userId) || !isValidIdentifier(entryName))
            throw new IllegalArgumentException("Invalid identifier");
        if (blob == null || blob.length < IV_SIZE + MAC_SIZE + 4)
            throw new IllegalArgumentException("Blob too short");
        if (blob.length > IV_SIZE + MAC_SIZE + 4 + MAX_ENTRY_SIZE)
            throw new IllegalArgumentException("Blob too large");

        // Verify MAC before accepting
        verifyBlobIntegrity(blob);

        String entryId = userId + ":" + entryName;
        storage.put(entryId, blob);
        acl.put(entryId, userId);
        return entryId;
    }

    private byte[] decryptBlob(byte[] blob) throws Exception {
        if (blob.length < IV_SIZE + MAC_SIZE + 4)
            throw new SecurityException("Corrupted blob");

        byte[] iv = Arrays.copyOfRange(blob, 0, IV_SIZE);
        byte[] storedTag = Arrays.copyOfRange(blob, IV_SIZE, IV_SIZE + MAC_SIZE);

        // Read declared length from blob
        int offset = IV_SIZE + MAC_SIZE;
        int declaredLength = ((blob[offset] & 0xFF) << 24) |
                            ((blob[offset+1] & 0xFF) << 16) |
                            ((blob[offset+2] & 0xFF) << 8) |
                            (blob[offset+3] & 0xFF);

        // Validate declared length against blob size
        int headerSize = IV_SIZE + MAC_SIZE + 4;
        int availableData = blob.length - headerSize;

        if (declaredLength < 0 || declaredLength > MAX_ENTRY_SIZE)
            throw new SecurityException("Invalid length field");
        if (declaredLength > availableData)
            throw new SecurityException("Declared length exceeds available data");

        // Extract ciphertext using declared length
        byte[] ciphertext = Arrays.copyOfRange(blob, headerSize, headerSize + declaredLength);

        // Recompute MAC over iv || length || ciphertext
        byte[] lengthBytes = Arrays.copyOfRange(blob, offset, offset + 4);
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(macKey, "HmacSHA256"));
        mac.update(iv);
        mac.update(lengthBytes);
        mac.update(ciphertext);
        byte[] computedTag = mac.doFinal();

        if (!MessageDigest.isEqual(storedTag, computedTag))
            throw new SecurityException("MAC verification failed");

        // Decrypt
        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(encKey, "AES"),
                   new IvParameterSpec(iv));
        return cipher.doFinal(ciphertext);
    }

    private void verifyBlobIntegrity(byte[] blob) throws Exception {
        byte[] iv = Arrays.copyOfRange(blob, 0, IV_SIZE);
        byte[] storedTag = Arrays.copyOfRange(blob, IV_SIZE, IV_SIZE + MAC_SIZE);

        int offset = IV_SIZE + MAC_SIZE;
        int declaredLength = ((blob[offset] & 0xFF) << 24) |
                            ((blob[offset+1] & 0xFF) << 16) |
                            ((blob[offset+2] & 0xFF) << 8) |
                            (blob[offset+3] & 0xFF);

        if (declaredLength < 0 || declaredLength > MAX_ENTRY_SIZE)
            throw new SecurityException("Invalid length");

        int headerSize = IV_SIZE + MAC_SIZE + 4;
        int availableData = blob.length - headerSize;
        if (declaredLength > availableData)
            throw new SecurityException("Declared length exceeds blob size");

        byte[] ciphertext = Arrays.copyOfRange(blob, headerSize, headerSize + declaredLength);
        byte[] lengthBytes = Arrays.copyOfRange(blob, offset, offset + 4);

        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(macKey, "HmacSHA256"));
        mac.update(iv);
        mac.update(lengthBytes);
        mac.update(ciphertext);
        byte[] computedTag = mac.doFinal();

        if (!MessageDigest.isEqual(storedTag, computedTag))
            throw new SecurityException("MAC verification failed");
    }

    private boolean isValidIdentifier(String id) {
        if (id == null || id.isEmpty() || id.length() > 64) return false;
        for (char c : id.toCharArray()) {
            if (!Character.isLetterOrDigit(c) && c != '_' && c != '-') return false;
        }
        return true;
    }
}
